import { join } from "node:path";

export const deploymentDestination = (slug: string) => join(".agents", "skills", slug);
import { expect, test } from "bun:test";
import { join } from "node:path";
import { deploymentDestination } from "./deployment-links.ts";

const deploymentTimeoutMilliseconds = 15_000;
test("maps the existing skill destination", () => {
  expect(deploymentDestination("existing-skill")).toBe(join(".agents", "skills", "existing-skill"));
}, deploymentTimeoutMilliseconds);

test("maps the new deployment-link destination", () => {
  const destinations = [deploymentDestination("example-skill")];
  expect(destinations).toContain(join(".agents", "skills", "example-skill"));
});
